// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver.code.length == 0); // plain EOA so transfer never fails on gas
        bound(amount, 2, 1 ether); // bug only visible when amount != 1
        vm.deal(address(c), amount); // reference must not revert from insufficient balance
        uint256 before = receiver.balance;
        c.sendTo(receiver, amount);
        assertEq(receiver.balance - before, amount);
    }
}
